      "why": "Determines whether the core dramatic state is survival, romance, mystery, political maneuvering, etc.",
      "options": [
        "Survival / adventure in a hostile world",
        "Romance or relationship drama",
        "Mystery or investigation",
        "Political intrigue / faction conflict",
        "Something else (describe)"
      ]
    },
    {
      "id": "protagonist",
      "text": "Who is the protagonist and what do they want most?",
      "why": "The protagonist's goal usually becomes the spine quality that anchors progress gates."
    },
    {
      "id": "stakes",
      "text": "What's the central tension or threat that escalates over the story?",
      "why": "Lets me define a tension/danger quality that rises and falls with the arc.",
      "options": [
        "A pursuing enemy or deadline",
        "A secret that could be exposed",
        "A relationship that could break",
        "A resource or ally that could be lost",
        "Something else (describe)"
      ]
    }
  ]
}

